{"command":"create","file_text":"import type pg from 'pg';
import { pool } from '../../database/src/pool.js';

export type ErasureStatus = 'pending' | 'processing' | 'completed' | 'failed';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  status: ErasureStatus;
  attempts: number;
  last_error: string | null;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
}

/** Public response shape uses camelCase keys and ISO timestamps. */
export function serializeErasureRequest(row: ErasureRequestRow): Record<string, unknown> {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
    lastError: row.last_error,
  };
}

export class ErasureRequestRepository {
  async findByCustomer(merchantId: string, customerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT id,merchant_id,customer_id,status,attempts,last_error,created_at,updated_at,completed_at
       FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async findByCustomerForUpdate(client: pg.PoolClient, merchantId: string, customerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `SELECT id,merchant_id,customer_id,status,attempts,last_error,created_at,updated_at,completed_at
       FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2 FOR UPDATE`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async findForMerchant(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT id,merchant_id,customer_id,status,attempts,last_error,created_at,updated_at,completed_at
       FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  async create(
    client: pg.PoolClient,
    input: { id: string; merchantId: string; customerId: string; idempotencyKey: string },
  ): Promise<ErasureRequestRow> {
    const result = await client.query<ErasureRequestRow>(
      `INSERT INTO customers.erasure_requests(id,merchant_id,customer_id,idempotency_key,status)
       VALUES($1,$2,$3,$4,'pending')
       RETURNING id,merchant_id,customer_id,status,attempts,last_error,created_at,updated_at,completed_at`,
      [input.id, input.merchantId, input.customerId, input.idempotencyKey],
    );
    return result.rows[0]!;
  }

  async markProcessing(client: pg.PoolClient, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `UPDATE customers.erasure_requests
       SET status='processing',attempts=attempts+1,updated_at=now(),last_error=NULL
       WHERE id=$1 AND status IN ('pending','failed')
       RETURNING id,merchant_id,customer_id,status,attempts,last_error,created_at,updated_at,completed_at`,
      [requestId],
    );
    return result.rows[0];
  }

  async markCompleted(client: pg.PoolClient, requestId: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='completed',completed_at=now(),updated_at=now(),last_error=NULL WHERE id=$1`,
      [requestId],
    );
  }

  async markFailed(client: pg.PoolClient, requestId: string, errorCode: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='failed',last_error=$2,updated_at=now() WHERE id=$1`,
      [requestId, errorCode],
    );
  }

  /** Claims runnable erasure requests whose cleanup job has not yet been queued. */
  async pendingRequestIds(limit = 50): Promise<{ id: string; merchant_id: string; customer_id: string }[]> {
    const result = await pool.query<{ id: string; merchant_id: string; customer_id: string }>(
      `SELECT id,merchant_id,customer_id FROM customers.erasure_requests
       WHERE status IN ('pending','failed') ORDER BY updated_at LIMIT $1`,
      [limit],
    );
    return result.rows;
  }
}","path":"/workspace/source/packages/privacy/src/erasure-request-repository.ts"}

