{"command":"create","file_text":"import type pg from 'pg';

/** Pseudonymous markers left on the retained customer row so it cannot be recreated and the deletion is traceable. */
export function erasedEmail(requestId: string): string {
  return `erased:${requestId}@erased.local`;
}

export function erasedExternalReference(requestId: string): string {
  return `erased:${requestId}`;
}

export interface CustomerPii {
  emails: string[];
}

export class ErasureCleanupRepository {
  /** Loads the customer's contactable email addresses before they are removed. */
  async loadCustomerPii(client: pg.PoolClient, merchantId: string, customerId: string): Promise<CustomerPii> {
    const customer = await client.query<{ email: string }>(
      `SELECT email FROM customers.customers WHERE merchant_id=$1 AND id=$2`, [merchantId, customerId],
    );
    const emails = new Set<string>();
    if (customer.rows[0]?.email) emails.add(customer.rows[0].email);
    const contacts = await client.query<{ value: string }>(
      `SELECT value FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2 AND kind='email'`, [merchantId, customerId],
    );
    for (const row of contacts.rows) if (row.value) emails.add(row.value);
    const deliveries = await client.query<{ destination: string }>(
      `SELECT DISTINCT destination FROM operations.email_deliveries WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId],
    );
    for (const row of deliveries.rows) if (row.destination) emails.add(row.destination);
    return { emails: [...emails] };
  }

  /** Anonymizes the retained customer row and marks it erased so normal processing cannot recreate its data. */
  async anonymizeCustomer(client: pg.PoolClient, merchantId: string, customerId: string, requestId: string): Promise<void> {
    await client.query(
      `UPDATE customers.customers
       SET email=$3,name='Erased Customer',phone=NULL,external_reference=$4,metadata='{}'::jsonb,
           status='erased',erased_at=now(),erasure_request_id=$5,updated_at=now()
       WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId, erasedEmail(requestId), erasedExternalReference(requestId), requestId],
    );
  }

  async deleteAddresses(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(`DELETE FROM customers.addresses WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  }

  async deleteContacts(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(`DELETE FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  }

  async deletePaymentMethods(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(`DELETE FROM customers.payment_method_refs WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  }

  async deleteProviderCustomerMappings(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `DELETE FROM customers.provider_customer_mappings WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId],
    );
  }

  async anonymizeProviderSandboxCustomers(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE provider_sandbox.customers
       SET email='erased@erased.local',name='Erased Customer',external_reference='erased',updated_at=now()
       WHERE merchant_id=$1 AND payflow_customer_id=$2`,
      [merchantId, customerId],
    );
  }

  async deleteSupportArtifacts(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    const tickets = await client.query<{ id: string }>(
      `DELETE FROM customers.support_participants WHERE customer_id=$1 RETURNING ticket_id`, [customerId],
    );
    const ticketIds = tickets.rows.map((row) => row.id);
    if (ticketIds.length) {
      await client.query(`DELETE FROM customers.support_messages WHERE merchant_id=$1 AND ticket_id=ANY($2::uuid[])`, [merchantId, ticketIds]);
      await client.query(`DELETE FROM customers.support_tickets WHERE merchant_id=$1 AND id=ANY($2::uuid[])`, [merchantId, ticketIds]);
    }
  }

  /** Anonymizes PII inside retained payment records while preserving their financial meaning. */
  async anonymizePayments(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE payments.payment_intents
       SET customer_snapshot=jsonb_build_object('id',$3::text,'status','erased')
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, customerId],
    );
    await client.query(
      `UPDATE payments.refunds SET customer_email=NULL WHERE merchant_id=$1 AND payment_intent_id IN
        (SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2)`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE payments.invoices SET billing_snapshot=jsonb_build_object('customerId',$3::text,'status','erased')
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, customerId],
    );
  }

  async redactAuditLogs(client: pg.PoolClient, customerId: string): Promise<void> {
    await client.query(
      `UPDATE platform.audit_logs SET metadata='{}'::jsonb WHERE target_type='customer' AND target_id=$1`,
      [customerId],
    );
  }

  async deleteAnalyticsEvents(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(`DELETE FROM operations.analytics_events WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  }

  async deleteNotifications(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(`DELETE FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
    await client.query(`DELETE FROM operations.notifications WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
    await client.query(`DELETE FROM operations.email_deliveries WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  }

  /** Cancels unpublished outbox events so retries cannot republish the customer's personal data. */
  async cancelPendingOutboxEvents(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE operations.outbox_events
       SET status='dead',locked_by=NULL,locked_at=NULL,lease_expires_at=NULL,
           last_error=COALESCE(last_error,'customer_erased')
       WHERE merchant_id=$1 AND aggregate_type='customer' AND aggregate_id=$2 AND status<>'published'`,
      [merchantId, customerId],
    );
  }

  /** Cancels pending background jobs that still carry the customer's personal data in their payload. */
  async cancelPendingJobs(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE operations.jobs
       SET status='dead',locked_by=NULL,locked_at=NULL,lease_expires_at=NULL,
           last_error=COALESCE(last_error,'customer_erased')
       WHERE merchant_id=$1 AND payload->>'customerId'=$2 AND status<>'completed'`,
      [merchantId, customerId],
    );
  }

  async listReceiptManifests(client: pg.PoolClient, merchantId: string, customerId: string): Promise<{ object_key: string; checksum: string }[]> {
    const result = await client.query<{ object_key: string; checksum: string }>(
      `SELECT object_key,checksum FROM operations.document_manifests
       WHERE merchant_id=$1 AND customer_id=$2 AND document_type='receipt'`, [merchantId, customerId],
    );
    return result.rows;
  }

  async listInvoiceManifests(client: pg.PoolClient, merchantId: string, customerId: string): Promise<{ object_key: string; checksum: string }[]> {
    const result = await client.query<{ object_key: string; checksum: string }>(
      `SELECT object_key,checksum FROM operations.document_manifests
       WHERE merchant_id=$1 AND customer_id=$2 AND document_type='invoice'`, [merchantId, customerId],
    );
    return result.rows;
  }

  /** Customer imports have no foreign key to a customer; scan merchant imports whose content references this customer. */
  async listImportsForCustomer(client: pg.PoolClient, merchantId: string, customerId: string): Promise<{ id: string; object_key: string }[]> {
    const imports = await client.query<{ id: string; object_key: string }>(
      `SELECT id,object_key FROM customers.customer_imports WHERE merchant_id=$1`, [merchantId],
    );
    return imports.rows.filter((row) => row.object_key.includes(customerId) || row.object_key === customerId);
  }

  async deleteImportRow(client: pg.PoolClient, importId: string): Promise<void> {
    await client.query(`DELETE FROM customers.customer_imports WHERE id=$1`, [importId]);
  }

  async deleteManifestByObjectKey(client: pg.PoolClient, objectKey: string): Promise<void> {
    await client.query(`DELETE FROM operations.document_manifests WHERE object_key=$1`, [objectKey]);
  }

  async updateManifestChecksum(client: pg.PoolClient, objectKey: string, checksum: string): Promise<void> {
    await client.query(`UPDATE operations.document_manifests SET checksum=$2 WHERE object_key=$1`, [objectKey, checksum]);
  }
}","path":"/workspace/source/packages/privacy/src/erasure-cleanup-repository.ts"}

