{"command":"create","file_text":"import { Redis } from 'ioredis';
import { config } from '../../config/src/index.js';
import { CUSTOMER_INDEX, searchClient } from '../../search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../../storage/src/minio.js';
import { deleteMailpitMessagesForRecipient } from '../../notifications/src/mailpit.js';

let redisConnection: Redis | undefined;
function redis(): Redis {
  redisConnection ??= new Redis(config().REDIS_URL);
  return redisConnection;
}

/** Removes the customer's projected profile from search and cache so it cannot be served again. */
export async function deleteSearchAndCacheProjections(merchantId: string, customerId: string): Promise<void> {
  await searchClient.delete(index=undefined as never, { index: CUSTOMER_INDEX, id: `${merchantId}:${customerId}` }).catch(() => undefined);
  await redis().del(`merchant:${merchantId}:customer:${customerId}`);
  await redis().del(`merchant:${merchantId}:customer:${customerId}:activity`);
}

export async function deleteMailpitForEmails(emails: string[]): Promise<void> {
  for (const email of emails) {
    if (!email) continue;
    try {
      await deleteMailpitMessagesForRecipient(email);
    } catch {
      // Mailpit may be temporarily unavailable; deletion is retried on the next attempt.
    }
  }
}

async function readObject(objectKey: string): Promise<string | undefined> {
  try {
    const stream = await objectStore.getObject(DOCUMENT_BUCKET, objectKey);
    const chunks: Buffer[] = [];
    for await (const chunk of stream as AsyncIterable<Buffer>) chunks.push(Buffer.from(chunk));
    return Buffer.concat(chunks).toString('utf8');
  } catch {
    return undefined;
  }
}

/** Anonymizes a stored customer-facing document while keeping its financial fields intact. */
async function redactDocument(objectKey: string, customerFields: string[]): Promise<{ rewritten: boolean; checksum: string | null }> {
  const body = await readObject(objectKey);
  if (!body) return { rewritten: false, checksum: null };
  let document: Record<string, unknown>;
  try {
    document = JSON.parse(body) as Record<string, unknown>;
  } catch {
    return { rewritten: false, checksum: null };
  }
  let changed = false;
  for (const field of customerFields) {
    if (field in document) {
      document[field] = { status: 'erased' };
      changed = true;
    }
  }
  if (!changed) return { rewritten: false, checksum: null };
  const rewritten = JSON.stringify(document);
  await objectStore.putObject(DOCUMENT_BUCKET, objectKey, rewritten, Buffer.byteLength(rewritten), { 'Content-Type': 'application/json' });
  return { rewritten: true, checksum: null };
}

export async function redactReceiptObject(objectKey: string): Promise<boolean> {
  const { rewritten } = await redactDocument(objectKey, ['customer', 'customerSnapshot']);
  return rewritten;
}

export async function redactInvoiceObject(objectKey: string): Promise<boolean> {
  const { rewritten } = await redactDocument(objectKey, ['customer', 'customerSnapshot']);
  return rewritten;
}

export async function deleteObject(objectKey: string): Promise<void> {
  try {
    await objectStore.removeObject(DOCUMENT_BUCKET, objectKey);
  } catch {
    // already removed
  }
}

export async function closeErasureExternalClients(): Promise<void> {
  if (redisConnection) await redisConnection.quit().catch(() => undefined);
}","path":"/workspace/source/packages/privacy/src/erasure-external.ts"}

