  try {
    await objectStore.removeObject(DOCUMENT_BUCKET, objectKey);
  } catch {
    // already removed
  }
}

/** Finds import objects whose content references the erased customer and returns them for deletion. */
export async function matchAndDeleteImports(
  imports: { id: string; object_key: string }[],
  customerId: string,
): Promise<{ id: string; object_key: string }[]> {
  const matched: { id: string; object_key: string }[] = [];
  for (const item of imports) {
    const body = await readObject(item.object_key);
    if (!body) continue;
    try {
      const record = JSON.parse(body) as Record<string, unknown>;
      if (record.customerId === customerId || record.customer_id === customerId) matched.push(item);
    } catch {
      continue;
    }
  }
  return matched;
}

