import {
  claimJob,
  completeJob,
  failJob,
  recoverExpiredJobLeases,
  type ClaimedJob,
} from '../../operations/src/job-lifecycle.js';
import { transaction } from '../../database/src/pool.js';
import { logger } from '../../observability/src/logger.js';
import { ErasureProcessor, type ErasureJobPayload } from './erasure-processor.js';
import { ErasureRequestRepository } from './erasure-request-repository.js';

const processor = new ErasureProcessor();
const requests = new ErasureRequestRepository();

async function processOne(job: ClaimedJob<ErasureJobPayload>): Promise<void> {
  try {
    await processor.process(job.payload);
    await transaction(async (client) => await completeJob(client, job));
  } catch (error) {
    logger.error({ error, jobId: job.id }, 'erasure job failed');
    await transaction(async (client) => await failJob(client, job, error));
  }
}

/** Continuously claims and runs erasure jobs until the abort signal fires. */
export async function runErasureWorker(workerId: string, signal: AbortSignal): Promise<void> {
  let lastLeaseRecovery = 0;
  while (!signal.aborted) {
    if (Date.now() - lastLeaseRecovery > 30_000) {
      await recoverExpiredJobLeases('erasure');
      lastLeaseRecovery = Date.now();
    }
    const job = await claimJob<ErasureJobPayload>('erasure', workerId);
    if (!job) {
      await new Promise((resolve) => setTimeout(resolve, 250));
      continue;
    }
    await processOne(job);
  }
}

/** Re-enqueues cleanup jobs for requests left failed by a previous run. */
export async function recoverFailedErasureRequests(): Promise<void> {
  const pending = await (await import('../../database/src/pool.js')).pool.query<{ id: string; merchant_id: string; customer_id: string; status: string }>(
    `SELECT id,merchant_id,customer_id,status FROM customers.erasure_requests WHERE status='failed'`,
  );
  for (const row of pending.rows) {
    await processor.requeueFailed({
      id: row.id,
      merchant_id: row.merchant_id,
      customer_id: row.customer_id,
      status: row.status as 'failed',
      attempts: 0,
      last_error: null,
      created_at: new Date(0),
      updated_at: new Date(0),
      completed_at: null,
    });
  }
  void requests;
}","path":"/workspace/source/packages/privacy/src/erasure-worker.ts"}

