{"command":"create","file_text":"import { randomUUID } from 'node:crypto';
import { transaction } from '../../database/src/pool.js';
import { completeIdempotency, requestHash, reserveIdempotency } from '../../payment-service/src/idempotency.js';
import {
  ErasureRequestRepository,
  serializeErasureRequest,
  type ErasureRequestRow,
} from '../../privacy/src/erasure-request-repository.js';

const IDEMPOTENCY_SCOPE = 'erasure-request';

export class CustomerErasureService {
  constructor(private readonly requests = new ErasureRequestRepository()) {}

  async create(merchantId: string, customerId: string, idempotencyKey: string): Promise<{ status: number; body: Record<string, unknown> }> {
    const hash = requestHash(customerId);
    return await transaction(async (client) => {
      const replay = await reserveIdempotency(client, merchantId, IDEMPOTENCY_SCOPE, idempotencyKey, hash);
      if (replay) return { status: replay.status, body: replay.body as Record<string, unknown> };

      const existing = await this.requests.findByCustomerForUpdate(client, merchantId, customerId);
      if (existing) {
        await completeIdempotency(client, merchantId, IDEMPOTENCY_SCOPE, idempotencyKey, 202, serializeErasureRequest(existing));
        return { status: 202, body: serializeErasureRequest(existing) };
      }

      const created = await this.requests.create(client, {
        id: randomUUID(),
        merchantId,
        customerId,
        idempotencyKey,
      });
      await client.query(
        `INSERT INTO operations.jobs(id,queue,job_type,merchant_id,payload)
         VALUES($1,'erasure','erase_customer',$2,$3)`,
        [randomUUID(), merchantId, { requestId: created.id, merchantId, customerId }],
      );
      const body = serializeErasureRequest(created);
      await completeIdempotency(client, merchantId, IDEMPOTENCY_SCOPE, idempotencyKey, 202, body);
      return { status: 202, body };
    });
  }

  async get(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    return await this.requests.findForMerchant(merchantId, requestId);
  }
}","path":"/workspace/source/apps/customer-service/src/erasure-service.ts"}

