{"command":"str_replace","new_str":"/** Requeues a retry job for a failed request so the service converges without a fresh API call. */
  async requeueFailed(request: ErasureRequestRow): Promise<void> {
    if (request.status !== 'failed') return;
    await transaction(async (client) => {
      // Avoid enqueuing duplicate retries across worker restarts: only add a job when no
      // runnable erasure job already exists for this request.
      const existing = await client.query<{ id: string }>(
        `SELECT id FROM operations.jobs
         WHERE queue='erasure' AND payload->>'requestId'=$1 AND status IN ('pending','retry','processing') LIMIT 1`,
        [request.id],
      );
      if (existing.rows[0]) return;
      await client.query(
        `INSERT INTO operations.jobs(id,queue,job_type,merchant_id,payload)
         VALUES($1,'erasure','erase_customer',$2,$3)`,
        [randomUUID(), request.merchant_id, { requestId: request.id, merchantId: request.merchant_id, customerId: request.customer_id }],
      );
