{"command":"create","file_text":"import { randomUUID } from 'node:crypto';
import assert from 'node:assert/strict';

const GATEWAY = process.env.GATEWAY_URL ?? 'http://localhost:3000';
const KEY = process.env.PAYFLOW_API_KEY ?? 'pf_local_dev_northstar_4ad1539de977';
const PG = process.env.POSTGRES_URL ?? 'postgres://payflow:payflow@localhost:5432/payflow';

async function api(path, method = 'GET', body, extra = {}) {
  const headers = { authorization: `Bearer ${KEY}`, ...extra };
  const init = { method, headers };
  if (body !== undefined) { headers['content-type'] = 'application/json'; init.body = JSON.stringify(body); }
  const res = await fetch(`${GATEWAY}${path}`, init);
  const text = await res.text();
  let json; try { json = JSON.parse(text); } catch { json = text; }
  return { status: res.status, body: json };
}

const suffix = Date.now().toString(36);

// Create a customer with a payment to verify financial records are retained but PII redacted.
const customer = await api('/v1/customers', 'POST', {
  externalReference: `erase-e2e-${suffix}`, email: `erase-e2e+${suffix}@example.test`,
  name: 'Erase E2E', phone: '+1-415-555-9090', metadata: { segment: 'retail', source: 'e2e' },
});
assert.equal(customer.status, 201, `create customer failed: ${JSON.stringify(customer.body)}`);
const customerId = customer.body.id;
console.log('created customer', customerId);

// Unknown customer -> 404
const unknown = await api(`/v1/customers/${randomUUID()}/erasure-requests`, 'POST', undefined, { 'idempotency-key': `unknown-${suffix}` });
assert.equal(unknown.status, 404, `expected 404, got ${unknown.status} ${JSON.stringify(unknown.body)}`);

// Missing idempotency key -> 400
const noKey = await api(`/v1/customers/${customerId}/erasure-requests`, 'POST');
assert.equal(noKey.status, 400, `expected 400, got ${noKey.status} ${JSON.stringify(noKey.body)}`);

// Create erasure request
const created = await api(`/v1/customers/${customerId}/erasure-requests`, 'POST', undefined, { 'idempotency-key': `e2e-key-${suffix}` });
assert.equal(created.status, 202, `expected 202, got ${created.status} ${JSON.stringify(created.body)}`);
const requestId = created.body.id;
