    updatedAt: '2026-08-20T12:00:00.000Z',
    completedAt: null,
    lastError: null,
  });
});

test('erasure request serialization never leaks the merchant id', () => {
  const body = serializeErasureRequest(row());
  assert.equal('merchant_id' in body, false);
  assert.equal('merchantId' in body, false);
});

test('completed erasure requests expose a completion timestamp and stable error-free state', () => {
