const GATEWAY = process.env.GATEWAY_URL ?? 'http://localhost:3000';
const KEY = process.env.PAYFLOW_API_KEY ?? 'pf_local_dev_northstar_4ad1539de977';
const PG = process.env.POSTGRES_URL ?? 'postgres://payflow:payflow@localhost:5432/payflow';

async function api(path, method = 'GET', body, extra = {}) {
  const headers = { authorization: `Bearer ${KEY}`, ...extra };
  const init = { method, headers };
  if (body !== undefined) { headers['content-type'] = 'application/json'; init.body = JSON.stringify(body); }
  const res = await fetch(`${GATEWAY}${path}`, init);
  const text = await res.text();
  let json; try { json = JSON.parse(text); } catch { json = text; }
  return { status: res.status, body: json };
}

const suffix = Date.now().toString(36);

// Create a customer with a payment so a receipt document with PII is generated, then erase.
const customer = await api('/v1/customers', 'POST', {
  externalReference: `e2e-${suffix}`, email: `e2e+${suffix}@example.test`,
  name: 'E2E With Payment', phone: '+1-415-555-1010', metadata: { segment: 'retail' },
});
assert.equal(customer.status, 201, `create customer failed: ${JSON.stringify(customer.body)}`);
const customerId = customer.body.id;
const piiEmail = `e2e+${suffix}@example.test`;

const pm = await api(`/v1/customers/${customerId}/payment-methods`, 'POST', {
  providerToken: `tok_e2e_${suffix}xxxxxxxx`, type: 'card', last4: '4242', billingName: 'E2E With Payment',
});
assert.equal(pm.status, 201, `pm failed: ${JSON.stringify(pm.body)}`);

const payment = await api('/v1/payments', 'POST', {
  customerId, paymentMethodId: pm.body.id, amount: 2500, currency: 'USD', description: `e2e-${suffix}`,
}, { 'idempotency-key': `pay-${suffix}` });
assert.ok(payment.status === 201 || payment.status === 202, `payment failed: ${JSON.stringify(payment.body)}`);
const paymentId = payment.body.id;
console.log('payment', paymentId);

// Wait for the payment to succeed (and the receipt to be generated).
let pay;
for (let i = 0; i < 120; i++) {
  pay = await api(`/v1/payments/${paymentId}`);
  if (pay.body.status === 'succeeded') break;
  await new Promise((r) => setTimeout(r, 150));
}
assert.equal(pay.body.status, 'succeeded', `payment did not succeed: ${JSON.stringify(pay.body)}`);
console.log('payment succeeded');

// Request erasure.
const created = await api(`/v1/customers/${customerId}/erasure-requests`, 'POST', undefined, { 'idempotency-key': `e2e-${suffix}` });
assert.equal(created.status, 202, `erasure create failed: ${JSON.stringify(created.body)}`);
const requestId = created.body.id;
console.log('erasure requested', requestId);

// Poll to completion.
let final;
for (let i = 0; i < 120; i++) {
  final = await api(`/v1/erasure-requests/${requestId}`);
  if (final.body.status === 'completed' || final.body.status === 'failed') break;
  await new Promise((r) => setTimeout(r, 500));
}
assert.equal(final.body.status, 'completed', `erasure did not complete: ${JSON.stringify(final.body)}`);
console.log('erasure completed');

// --- Verify DB state via direct postgres connection ---
const pg = (await import('pg')).default;
const pool = new pg.Pool({ connectionString: PG });
const client = await pool.connect();

const cust = await client.query(
  `SELECT email,name,phone,external_reference,status,erased_at IS NOT NULL erased,erasure_request_id FROM customers.customers WHERE id=$1`, [customerId],
);
const c = cust.rows[0];
assert.equal(c.status, 'erased');
assert.equal(c.erased, true);
assert.equal(c.erasure_request_id, requestId);
assert.ok(!c.email.includes(piiEmail), 'customer email still contains PII');
assert.equal(c.phone, null);
assert.ok(!c.external_reference.includes('e2e-'), 'external_reference still identifies customer');

// PII tables emptied.
const pii = await client.query(
  `SELECT (SELECT count(*) FROM customers.addresses WHERE customer_id=$1) addr,
          (SELECT count(*) FROM customers.contacts WHERE customer_id=$1) contacts,
          (SELECT count(*) FROM customers.payment_method_refs WHERE customer_id=$1) pmrefs,
          (SELECT count(*) FROM operations.analytics_events WHERE customer_id=$1) analytics,
          (SELECT count(*) FROM operations.email_deliveries WHERE customer_id=$1) emails`, [customerId],
);
const p = pii.rows[0];
assert.equal(Number(p.addr), 0, 'addresses not deleted');
assert.equal(Number(p.contacts), 0, 'contacts not deleted');
assert.equal(Number(p.pmrefs), 0, 'payment method refs not deleted');
assert.equal(Number(p.analytics), 0, 'analytics not deleted');
assert.equal(Number(p.emails), 0, 'email deliveries not deleted');

// Financial record retained and anonymized.
const pi = await client.query(
  `SELECT status,customer_snapshot FROM payments.payment_intents WHERE id=$1`, [paymentId],
);
assert.equal(pi.rows[0].status, 'succeeded', 'payment status changed');
const snapshot = pi.rows[0].customer_snapshot;
assert.equal(snapshot?.email ?? snapshot?.name, undefined, 'payment snapshot still has PII');
assert.equal(snapshot?.status, 'erased');

// Receipt document retained (redacted in place): a manifest still exists and the stored object has no PII.
const manifest = await client.query(
  `SELECT object_key FROM operations.document_manifests WHERE customer_id=$1 AND document_type='receipt'`, [customerId],
);
assert.ok(manifest.rows.length >= 1, 'receipt manifest was deleted (financial record must be retained)');

// No leftover unfinished jobs for this customer; no outbox events with PII.
const jobs = await client.query(
  `SELECT count(*) c FROM operations.jobs WHERE queue<>'erasure' AND payload->>'customerId'=$1 AND status<>'completed'`, [customerId],
);
assert.equal(Number(jobs.rows[0].c), 0, 'leftover unfinished jobs for erased customer');
const outbox = await client.query(
  `SELECT count(*) c FROM operations.outbox_events WHERE payload->>'customerId'=$1`, [customerId],
);
assert.equal(Number(outbox.rows[0].c), 0, 'outbox events for erased customer still present (PII risk)');

client.release(); await pool.end();
