{"command":"str_replace","new_str":"/** Removes the customer's personal data from the outbox: unpublished events are deleted so they
 *  can never republish PII, while published events are redacted in place so retained financial
 *  events keep their meaning without identifying the deleted customer. */
  async cancelPendingOutboxEvents(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
