{"command":"create","file_text":"import assert from 'node:assert/strict';

const GATEWAY = process.env.GATEWAY_URL ?? 'http://localhost:3000';
const KEY = process.env.PAYFLOW_API_KEY ?? 'pf_local_dev_northstar_4ad1539de977';
const OTHER_KEY = process.env.OTHER_API_KEY ?? 'pf_local_dev_bluebird_924bd90d2201';

async function api(path, method = 'GET', body, extra = {}, key = KEY) {
  const headers = { authorization: `Bearer ${key}`, ...extra };
  const init = { method, headers };
  if (body !== undefined) { headers['content-type'] = 'application/json'; init.body = JSON.stringify(body); }
  const res = await fetch(`${GATEWAY}${path}`, init);
  const text = await res.text();
  let json; try { json = JSON.parse(text); } catch { json = text; }
  return { status: res.status, body: json };
}

const suffix = Date.now().toString(36);

// 1. Create a customer that owns a completed payment, then erase via the public API.
const customer = await api('/v1/customers', 'POST', {
  externalReference: `final-${suffix}`, email: `final+${suffix}@example.test`,
  name: 'Final Verify', phone: '+1-415-555-2020', metadata: { plan: 'pro' },
});
assert.equal(customer.status, 201);
const customerId = customer.body.id;

const pm = await api(`/v1/customers/${customerId}/payment-methods`, 'POST', {
  providerToken: `tok_final_${suffix}xxxxxx`, type: 'card', last4: '0001', billingName: 'Final Verify',
});
assert.equal(pm.status, 201);

const payment = await api('/v1/payments', 'POST', {
  customerId, paymentMethodId: pm.body.id, amount: 4200, currency: 'USD', description: `final-${suffix}`,
}, { 'idempotency-key': `pay-${suffix}` });
assert.ok(payment.status === 201 || payment.status === 202);
const paymentId = payment.body.id;

// Wait for the payment to succeed so a receipt document is stored.
let pay;
for (let i = 0; i < 120; i++) {
  pay = await api(`/v1/payments/${paymentId}`);
  if (pay.body.status === 'succeeded') break;
  await new Promise((r) => setTimeout(r, 150));
}
assert.equal(pay.body.status, 'succeeded');

// 2. POST erasure-request: unknown customer -> 404.
const unknown = await api('/v1/customers/00000000-0000-0000-0000-000000000000/erasure-requests', 'POST', undefined, { 'idempotency-key': `u-${suffix}` });
assert.equal(unknown.status, 404);

// 3. POST erasure-request: missing idempotency key -> 400.
const noKey = await api(`/v1/customers/${customerId}/erasure-requests`, 'POST', undefined, {});
assert.equal(noKey.status, 400);

// 4. POST erasure-request: accepted -> 202 with id + status.
const created = await api(`/v1/customers/${customerId}/erasure-requests`, 'POST', undefined, { 'idempotency-key': `final-${suffix}` });
assert.equal(created.status, 202);
assert.ok(created.body.id, 'response must include id');
assert.equal(created.body.status, 'pending');
const requestId = created.body.id;

// 5. Idempotency: same key returns the same request id.
const again = await api(`/v1/customers/${customerId}/erasure-requests`, 'POST', undefined, { 'idempotency-key': `final-${suffix}` });
assert.equal(again.status, 202);
assert.equal(again.body.id, requestId);

// 6. Duplicate (different key) while pending -> 409.
const dup = await api(`/v1/customers/${customerId}/erasure-requests`, 'POST', undefined, { 'idempotency-key': `other-${suffix}` });
assert.equal(dup.status, 409);

// 7. GET status: cross-tenant isolation -> 404 for other merchant.
const cross = await api(`/v1/erasure-requests/${requestId}`, 'GET', undefined, {}, OTHER_KEY);
assert.equal(cross.status, 404);

// 8. Poll GET until completed.
let final;
for (let i = 0; i < 120; i++) {
  final = await api(`/v1/erasure-requests/${requestId}`);
  if (final.body.status === 'completed' || final.body.status === 'failed') break;
  await new Promise((r) => setTimeout(r, 500));
}
assert.equal(final.body.status, 'completed', `erasure did not complete: ${JSON.stringify(final.body)}`);
assert.equal(final.body.lastError, null);

// 9. Completed request for an already-erased customer -> 409 (cannot re-request).
const reRequest = await api(`/v1/customers/${customerId}/erasure-requests`, 'POST', undefined, { 'idempotency-key': `redone-${suffix}` });
assert.equal(reRequest.status, 409);

console.log(JSON.stringify({ customerId, paymentId, requestId, status: final.body.status, contract: 'verified' }));","path":"/workspace/source/scripts/erasure-contract-check.mjs"}

